-- T049 — the manual time zone override kept (FR-131, FR-AUTH-10; owner's decision 2026-10-20).
-- Generated by `prisma migrate diff --from-config-datasource --to-schema prisma/schema --script`
-- against a database holding every migration before it.
--
-- What it lands: `users.timezone_overridden_at`, the instant the person chose the zone by hand
-- (ERD §2). `account.setTimezone` sets it; `account.reportDeviceTimezone`, called on every launch,
-- replaces the zone only while it is null, so a chosen zone survives a reinstall and another
-- device. Nullable, no default: every existing account reads as never overridden.

-- AlterTable
ALTER TABLE "users" ADD COLUMN     "timezone_overridden_at" TIMESTAMPTZ(6);
